def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    rows = []
    for r, row in enumerate(grid):
        cells = [c for c, v in enumerate(row) if v != bg]
        if len(cells) >= 2:
            rows.append((r, min(cells), max(cells)))
    rows.sort()
    if len(rows) >= 2:
        (r0, a, b), (r1, c, d) = rows[0], rows[-1]
        # Bars project from their right-hand half; short two-cell bars use both.
        def projected_cols(lo, hi):
            n = hi - lo + 1
            return range(lo + n // 2, hi + 1) if n > 2 else range(lo, hi + 1)
        markers = [v for v in counts if v != bg and v not in (grid[r0][a], grid[r1][c])]
        fill = markers[0] if markers else 7
        for rr in range(r0 + 1, h):
            for cc in projected_cols(a, b):
                if grid[rr][cc] == bg:
                    out[rr][cc] = fill
        for rr in range(r1 - 1, -1, -1):
            for cc in projected_cols(c, d):
                if grid[rr][cc] == bg:
                    out[rr][cc] = fill
        dots = [(r, c) for r in range(h) for c in range(w)
                if grid[r][c] == fill and (r, c) not in
                [(r0, x) for x in range(a, b+1)] + [(r1, x) for x in range(c, d+1)]]
        if dots:
            r, c = min(dots)
            out[r][c] = 4
    return out
