def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find the two solid horizontal bars, distinct from the sparse marker color.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    markers = [v for v in Counter(v for row in grid for v in row) if v != bg]
    marker_color = min(markers, key=lambda v: Counter(x for row in grid for x in row)[v])
    bars = []
    for r, row in enumerate(grid):
        cs = [c for c, v in enumerate(row) if v != bg and v != marker_color]
        if len(cs) >= 2:
            bars.append((r, min(cs), max(cs)))
    bars.sort()
    if len(bars) < 2:
        return out
    (rt, a, b), (rb, c, d) = bars[0], bars[-1]
    # Project the inward half of each end bar along the full perpendicular axis.
    top_cols = range(a, a + (b-a+1)//2)
    bottom_cols = range(c + (d-c+1)//2, d+1)
    for r in range(rt+1, h):
        for col in top_cols:
            if grid[r][col] == bg:
                out[r][col] = marker_color
    for r in range(0, rb):
        for col in bottom_cols:
            if grid[r][col] == bg:
                out[r][col] = marker_color
    # Highlight marker cells lying within a projected stripe.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker_color and out[r][c] == marker_color:
                out[r][c] = 4
    return out
