def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # Horizontal bars are the contiguous non-background runs at the edges.
    bars = []
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != bg]
        if len(cols) < 3:
            continue
        # Use the longest contiguous non-background run in this row.
        runs = []
        for c in cols:
            if not runs or c > runs[-1][-1] + 1:
                runs.append([c])
            else:
                runs[-1].append(c)
        run = max(runs, key=len)
        if len(run) >= 3:
            bars.append((r, run[0], run[-1]))
    out = [row[:] for row in grid]
    if len(bars) < 2:
        return out
    bars.sort()
    top, bottom = bars[0], bars[-1]
    # The bar's rightmost half projects vertically; sparse-object color fills it.
    marker = min((v for v in counts if v != bg), key=lambda v: counts[v])
    projected = []
    for r0, lo, hi in (top, bottom):
        width = (hi - lo + 1) // 2
        cols = list(range(hi - width + 1, hi + 1))
        projected.append(cols)
        for r in range(r0 + 1, h) if r0 == top[0] else range(0, r0):
            for c in cols:
                if grid[r][c] == bg:
                    out[r][c] = marker
    # Any original marker within a projected stripe is highlighted as 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and any(c in cols for cols in projected):
                out[r][c] = 4
    return out
