def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find horizontal bars distinct from background and sparse marker pixels.
    bars = []
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != bg]
        runs = []
        for c in cols:
            if not runs or c != runs[-1][-1] + 1:
                runs.append([c])
            else:
                runs[-1].append(c)
        for run in runs:
            if len(run) >= 2:
                bars.append((r, run[0], run[-1], grid[r][run[0]]))
    bars.sort()
    if len(bars) < 2:
        return out
    (rt, a, b, top_color), (rb, c, d, bottom_color) = bars[0], bars[-1]
    # Each bar projects its inward-facing half as a full vertical stripe.
    top_width = (b - a + 1) // 2
    bottom_width = (d - c + 1) // 2
    top_cols = range(a, a + top_width) if (a + b) // 2 < w // 2 else range(b - top_width + 1, b + 1)
    bottom_cols = range(c, c + bottom_width) if (c + d) // 2 < w // 2 else range(d - bottom_width + 1, d + 1)
    marker_colors = [v for v in Counter(x for row in grid for x in row) if v != bg and v not in (top_color, bottom_color)]
    fill = marker_colors[0] if marker_colors else 7
    for r in range(rt + 1, h):
        for col in top_cols:
            if grid[r][col] == bg:
                out[r][col] = fill
    for r in range(rb):
        for col in bottom_cols:
            if grid[r][col] == bg:
