def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    # Locate the two horizontal border bars and the sparse marker color.
    bars = []
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != bg]
        if len(cols) >= 2:
            bars.append((r, min(cols), max(cols), grid[r][cols[0]]))
    bars.sort()
    if len(bars) < 2:
        return out
    top, bottom = bars[0], bars[-1]
    (rt, a, b, top_color), (rb, c, d, bottom_color) = top, bottom
    colors = {v for row in grid for v in row if v != bg}
    dots = [v for v in colors if v not in (top_color, bottom_color)]
    fill = dots[0] if dots else 4
    top_width = (b - a + 1) // 2 if b - a + 1 > 2 else b - a + 1
    bottom_width = (d - c + 1) // 2 if d - c + 1 > 2 else d - c + 1
    top_cols = range(a, a + top_width) if a > w // 2 else range(b - top_width + 1, b + 1)
    bottom_cols = range(c + (d - c + 1) // 2, d + 1) if c < w // 2 else range(d - bottom_width + 1, d + 1)
    for r in range(rt + 1, h):
        for col in top_cols:
            if grid[r][col] == bg:
                out[r][col] = fill
    for r in range(rb):
        for col in bottom_cols:
            if grid[r][col] == bg:
                out[r][col] = fill
    for r in range(h):
        for col in range(w):
            if grid[r][col] == fill and ((r > rt and col in top_cols) or (r < rb and col in bottom_cols)):
                out[r][col] = 4
    return out
