def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # identify dominant background and all 2-cell bars; isolated colors extend
    # as rays toward bars that lie along their row or column.
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    bars=[]
    for r in range(h):
      c=0
      while c<w:
        v=grid[r][c]; e=c+1
        while e<w and grid[r][e]==v:e+=1
        if v!=bg and e-c>=2: bars.append(('h',r,c,e-1,v))
        c=e
    for c in range(w):
      r=0
      while r<h:
        v=grid[r][c];e=r+1
        while e<h and grid[e][c]==v:e+=1
        if v!=bg and e-r>=2: bars.append(('v',c,r,e-1,v))
        r=e
    barcells=set()
    for o,a,l,u,v in bars:
      if o=='h': barcells.update((a,x) for x in range(l,u+1))
      else: barcells.update((x,a) for x in range(l,u+1))
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==bg or (r,c) in barcells: continue
        opts=[]
        for o,a,l,u,v in bars:
          if o=='v' and a==c and (r<l or r>u):
            end=l if r<l else u; opts.append((abs(end-r), 'v', end))
          if o=='h' and a==r and (c<l or c>u):
            end=l if c<l else u; opts.append((abs(end-c), 'h', end))
        if opts:
          _,o,end=min(opts)
          out[r][c]=4
          if o=='h':
            step=1 if end>c else -1
            for x in range(c+step,end,step):
              if grid[r][x]==bg:out[r][x]=color
          else:
            step=1 if end>r else -1
            for y in range(r+step,end,step):
              if grid[y][c]==bg:out[y][c]=color
    return out
