def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Horizontal rails project their right-hand half vertically; projected
    # cells take the color of the sparse object, whose pixels become 4.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    bars = []
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != bg]
        runs = []
        for c in cols:
            if not runs or c != runs[-1][-1] + 1:
                runs.append([c])
            else:
                runs[-1].append(c)
        for run in runs:
            if len(run) >= 2:
                bars.append((r, run[0], run[-1], grid[r][run[0]]))
    if not bars:
        return out
    bar_colors = {bar[3] for bar in bars}
    marker_colors = [v for v in counts if v != bg and v not in bar_colors]
    if not marker_colors:
        return out
    fill = marker_colors[0]
    for r, lo, hi, _ in bars:
        width = (hi - lo + 1) // 2
        cols = range(hi - width + 1, hi + 1)
        rows = range(r + 1, h) if r < h // 2 else range(r - 1, -1, -1)
        for rr in rows:
            for c in cols:
                if grid[rr][c] == bg:
                    out[rr][c] = fill
                elif grid[rr][c] == fill:
                    out[rr][c] = 4
    return out
