def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Detect edge bars as contiguous same-color runs. Sparse objects project
    # perpendicular to the bars; source pixels change to 4.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bars = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            v = row[c]; e = c + 1
            while e < w and row[e] == v: e += 1
            if v != bg and e-c >= 2:
                bars.append((r, c, e-1, v))
            c = e
    barcells = {(r,c) for r,a,b,v in bars for c in range(a,b+1)}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in barcells: continue
            # nearest bar in same row, or in same column
            opts=[]
            for br,a,b,v in bars:
                if br == r and (c<a or c>b): opts.append((min(abs(c-a),abs(c-b)),'h',a if c<a else b))
                if a <= c <= b and br != r: opts.append((abs(br-r),'v',br))
            if not opts: continue
            _, axis, end = min(opts)
            out[r][c]=4
            if axis=='h':
                step=1 if end>c else -1
                for x in range(c+step,end,step):
                    if grid[r][x]==bg: out[r][x]=color
            else:
                step=1 if end>r else -1
                for y in range(r+step,end,step):
                    if grid[y][c]==bg: out[y][c]=color
    return out
