        for r in range(rt+1,h):
            for x in range(max(0,a-(b-a+1)),a):
                if grid[r][x]==8: out[r][x]=3
        for r in range(rb):
            for x in range(d+1,min(w,d+(d-c+1)+1)):
                if grid[r][x]==8: out[r][x]=3
    # The three isolated 2s make a connected stepped shape; their source cells
    # are highlighted 4, and adjacent bridge cells are filled with 2.
    dots=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    for r,c in dots: out[r][c]=4
    for i,(r,c) in enumerate(dots):
        for rr,cc in dots[i+1:]:
            if abs(r-rr)+abs(c-cc)==2:
                out[(r+rr)//2][(c+cc)//2]=2
