def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = []
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == 3]
        if len(cols) >= 2:
            bars.append((r, min(cols), max(cols)))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                targets = [(abs(br-r), br) for br, lo, hi in bars if lo <= c <= hi]
                if targets:
                    br = min(targets)[1]
                    step = 1 if br > r else -1
                    out[r][c] = 4
                    for rr in range(r+step, br, step):
                        if grid[rr][c] == 8:
                            out[rr][c] = 2
    return out
